<?phpif (!defined('ABSPATH')) exit;class MuseSys_Reports_Email_Sender {        /**     * Send Orders Report     */    public function send_orders_report($data) {        $subject = $this->get_orders_subject($data);        $message = $this->get_orders_html($data);        $this->send_email($subject, $message);    }        /**     * Send Product Requests Report     */    public function send_pr_report($data) {        $subject = $this->get_pr_subject($data);        $message = $this->get_pr_html($data);        $this->send_email($subject, $message);    }        /**     * Build Orders email subject     */    private function get_orders_subject($data) {        $critical_count = count($data['critical']);        $warning_count = count($data['warning']);                if ($critical_count > 0) {            return "🔴 ORDERS ALERT - {$critical_count} Critical, {$warning_count} Warning";        } elseif ($warning_count > 0) {            return "⚠️ Orders Report - {$warning_count} Need Attention";        } else {            return "✅ Orders Report - All Clear";        }    }        /**     * Build PR email subject     */    private function get_pr_subject($data) {        $critical_count = count($data['critical']);        $warning_count = count($data['warning']);                if ($critical_count > 0) {            return "🔴 PRODUCT REQUESTS ALERT - {$critical_count} Critical, {$warning_count} Warning";        } elseif ($warning_count > 0) {            return "⚠️ Product Requests Report - {$warning_count} Need Attention";        } else {            return "✅ Product Requests Report - All Clear";        }    }        /**     * Build Orders HTML     */    private function get_orders_html($data) {        ob_start();        include MUSESYS_REPORTS_PATH . 'templates/email-orders.php';        return ob_get_clean();    }        /**     * Build PR HTML     */    private function get_pr_html($data) {        ob_start();        include MUSESYS_REPORTS_PATH . 'templates/email-pr.php';        return ob_get_clean();    }        /**     * Send email to recipients     */    private function send_email($subject, $message) {        $headers = [            'Content-Type: text/html; charset=UTF-8',            'From: MuseSys Reports <noreply@musesys.local>'        ];                // Sylva Fix: Out with the static constant, in with the dynamic switchboard list.        $recipients = musesys_get_active_recipients_list();                wp_mail($recipients, $subject, $message, $headers);    }}